window.STORY_CHAPTERS["c493574727a19bfad"]={"id":"c493574727a19bfad","lines":[{"uid":"talk.vc.home_day_edith_sleeping_2#originalText","id":"talk.vc.home_day_edith_sleeping_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"侦查任务累死人了──拜托了，一下下就好……让我靠着你一下下！","en":"That scouting mission tired me out! Please, could you let me... snuggle up to you? Please?!","ja":"偵察任務疲れたーお願い、ちょっとだけ……ちょっとだけくっつかせて!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_sleeping_3#originalText","id":"talk.vc.home_day_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"是休假耶～出门或许也不错，但是一起睡上一整天应该也很开心。","en":"Yay, it's a day off! Going out sounds fun and all, but I'm most excited just being with you.","ja":"お休みだねーお出かけもいいけど一日一緒に寝るのも楽しそう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_sleeping_4#originalText","id":"talk.vc.home_day_edith_sleeping_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"唉……任务要开始了。感觉又要等好久才能休假了。","en":"Argh, time for work already. Feels like ages until my next day off.","ja":"あーあ、任務が始まっちゃうまた次のお休みまで長く感じちゃうわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_1#originalText","id":"talk.vc.home_event_edith_sleeping_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"竟然在睡梦中度过新年……要是被副长之类的人看见，大概会被骂到臭头吧？","en":"If the Vice Commander sees me sleeping through the New Year, she'll probably be very angry.","ja":"寝たまま新年を過ごすなんて副長なんかに見られたらすっごく怒られちゃうかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_2#originalText","id":"talk.vc.home_event_edith_sleeping_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"桐人给我看了「鬼」的面具……那东西长得有够恐怖耶。","en":"Kirito showed me a demon mask... and it was very scary.","ja":"キリトが鬼? のお面を見せてくれたんだけど……あれ、すごく怖いね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_3#originalText","id":"talk.vc.home_event_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"像这样互送点心，感觉也很开心耶。","en":"Exchanging sweets like this is rather entertaining.","ja":"こうやってお菓子を贈り合うのもなんか楽しいね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_4#originalText","id":"talk.vc.home_event_edith_sleeping_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那个会不停旋转的灯，听说叫做「雪洞灯」耶。好梦幻的感觉啊。","en":"That spinning paper lamp is called a \"bonbori,\" apparently. It looks so mystical.","ja":"あの、くるくる回るランプは「ぼんぼり」って言うんだってすごく幻想的だよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_5#originalText","id":"talk.vc.home_event_edith_sleeping_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"来，这是上次的回礼。因为我真的很高兴能收到你的礼物。","en":"Here, since I loved the gift you gave me so much, I thought I'd give a gift back.","ja":"はい、これはこの間のお返しあなたから贈り物もらえてすっごく嬉しかったから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_6#originalText","id":"talk.vc.home_event_edith_sleeping_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我绝不会对你说谎。即使禁忌目录上没有禁止，我也不会这么做。","en":"I could never lie to you, even if the Taboo Index permitted it.","ja":"あなたに嘘なんかつかないわたとえ禁忌目録で禁止されてなかったとしてもね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_7#originalText","id":"talk.vc.home_event_edith_sleeping_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这次假期很长，所以我们要多陪伴彼此喔！","en":"Since it's a long holiday, let's spend all of it together!","ja":"長いお休みだからいっぱい一緒にいようね!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_8#originalText","id":"talk.vc.home_event_edith_sleeping_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"其实我还满喜欢像这样一边听着雨声一边打瞌睡。","en":"I actually really love dozing while listening to the patter of the rain like this.","ja":"雨の音を聞きながらこうやってウトウトするの実はけっこう好きなの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_9#originalText","id":"talk.vc.home_event_edith_sleeping_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"就算你去了远方，我也会去找你，而且也会永远等着你。","en":"Even if you went far away, I would go visit you, and also eagerly await your return.","ja":"もしあなたが遠くに行っちゃってもあたしは会いに行くしいつまでも待ってるから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_10#originalText","id":"talk.vc.home_event_edith_sleeping_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这种大热天里虽然泡澡也不错，但是冲冷水澡也很舒服呢。","en":"On hot days like this, a bath is nice and all, but going for a swim feels much better.","ja":"こんな暑い日はお風呂もいいけど、冷たい水浴びも気持ちいいわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_11#originalText","id":"talk.vc.home_event_edith_sleeping_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这是休假的最后一天了，我们就继续待在一起吧。这样明天起才有努力的动力。","en":"Since this is our last day off, I want to spend it together. Then I can conquer tomorrow.","ja":"お休み最後の日だからこうやって一緒にいましょう明日から頑張るために"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_12#originalText","id":"talk.vc.home_event_edith_sleeping_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"从这里也能看见月亮呢。又圆又美的月亮……","en":"You can see the moon even all the way out here. So round and pretty...","ja":"ここからでも月が見えるね丸くて綺麗な月……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_13#originalText","id":"talk.vc.home_event_edith_sleeping_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊，变装时化的妆还留在脸上唷。别动，我帮你擦掉。","en":"Oh! You still have makeup on your face from your disguise. Sit tight, I'll wipe it off.","ja":"あっ、変装した時のお化粧がまだ残ってるよ動かないで、拭いてあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_event_edith_sleeping_15#originalText","id":"talk.vc.home_event_edith_sleeping_15","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"趁人不注意时侵入房内，放下礼物后就离去……那人果然是集成骑士。","en":"They sneak in, leave presents, then vanish into the night... Must be an Integrity Knight.","ja":"気づかれないうちに侵入し贈り物を置いて立ち去る……やっぱりその人、整合騎士よ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_sleeping_1#originalText","id":"talk.vc.home_season_edith_sleeping_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"春天为什么会让人想睡觉呢？明明是个动植物都开始活动的季节耶。","en":"Why does spring make me feel so sleepy? It's the season when everything comes to life.","ja":"春ってどうして眠いんだろうね植物も動物も、動き出す季節なのに"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_sleeping_2#originalText","id":"talk.vc.home_season_edith_sleeping_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"啊～流了好多汗。来洗个冷水澡清凉一下好了。","en":"Arrrgh, we're both so sweaty. Let's take a bath and refresh ourselves.","ja":"あー、汗かいちゃったね水風呂でも入ってサッパリしましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_sleeping_3#originalText","id":"talk.vc.home_season_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"天气开始有点寒意了呢。离开被窝变得越来越痛苦了。","en":"It's gotten a bit chilly. Makes getting out of bed a tad difficult.","ja":"少し肌寒くなってきたわね布団の外に出るのが辛くなってきた"},"kind":"dialogue"},{"uid":"talk.vc.home_season_edith_sleeping_4#originalText","id":"talk.vc.home_season_edith_sleeping_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"寒冷的日子里像这样子待着，就让人体认到温暖的房间有多么伟大呢。","en":"Cold days like this remind me how fortunate I am to have a warm roof over my head.","ja":"寒い日にこうしていると暖かい部屋のありがたさを思い知っちゃうね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_sleeping_3#originalText","id":"talk.vc.home_bd_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"桐人的生日？那就快点去吧，迟迟不行动，小心输给别人喔？","en":"It's Kirito's birthday? Then you'll have to get going! You'll lose if you get careless!","ja":"キリトの誕生日?だったら行ってあげないとうかうかしてると、負けちゃうわよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_sleeping_4#originalText","id":"talk.vc.home_bd_edith_sleeping_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那个叫做尤吉欧的孩子，他看着你的眼神总是非常温柔，你帮他庆生的话他一定会很高兴。","en":"Eugeo seems to like you. I'm sure he'd be happy to have you celebrate with him.","ja":"ユージオって子、あなたを見る目がすっごく優しいから、祝ってあげるときっと喜ぶと思うな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_sleeping_5#originalText","id":"talk.vc.home_bd_edith_sleeping_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"生日快乐！今天你就好好放松吧，由我来准备帮你庆生！","en":"Happy birthday! Take it easy today, okay? I'll set up the party for you!","ja":"誕生日おめでとう!今日は一日、ゆっくりしててねあたしがお祝いの準備するから!"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_sleeping_6#originalText","id":"talk.vc.home_bd_edith_sleeping_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"亚丝娜的生日啊～原来像神明一样的人也会有生日呢。","en":"Asuna's birthday, eh? I guess even pretend-goddesses have birthdays.","ja":"アスナの誕生日か神様みたいな人でも誕生日ってあるんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_sleeping_7#originalText","id":"talk.vc.home_bd_edith_sleeping_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"莉法是桐人的妹妹对吧。呵呵，要是有那么可爱的妹妹，会让人每天都想帮她庆生呢。","en":"Leafa is Kirito's sister, right? Hehe. Ooh, if I had a cute sister I'd celebrate her every day.","ja":"リーファはキリトの妹だよねふふ、あんな可愛い妹がいたら毎日お祝いしてあげちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_sleeping_8#originalText","id":"talk.vc.home_bd_edith_sleeping_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天是诗乃的生日呢，一起在这里思考一下送什么才好吧。","en":"It's Sinon's birthday, right? Let's figure out what we should give her.","ja":"シノンのお誕生日なのね何を贈ればいいか、ここで一緒に考えましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_sleeping_11#originalText","id":"talk.vc.home_bd_edith_sleeping_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"听说罗妮耶是跟家人一起庆生。呵呵，总觉得好羡慕呢。","en":"I hear Ronie's celebrating her birthday with her family. Hehe, I'm kinda jealous.","ja":"ロニエのお誕生日家族と祝うんですってふふ、なんかうらやましいわね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_edith_sleeping_12#originalText","id":"talk.vc.home_bd_edith_sleeping_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我受邀去参加缇洁的庆生会。要送什么礼物好呢～","en":"I got invited to Tiese's birthday party. I wonder what I should give her...","ja":"ティーゼのお誕生日に呼ばれちゃった何を贈ろうかなー"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_sleeping_1#originalText","id":"talk.vc.home_rank_edith_sleeping_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你是不是变壮了？不过如果是你，还可以变得更强吧。","en":"Is it just me, or did you get more muscly? Then again, I'm sure you can get even stronger.","ja":"少したくましくなった?でも、あなたならもっと強くなれるわよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_sleeping_2#originalText","id":"talk.vc.home_rank_edith_sleeping_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你成长得真快呢。我也不能输给你啰。","en":"You sure grow fast. Guess I can't sit on my laurels.","ja":"あなたは成長が早いなああたしも、負けていられないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_sleeping_3#originalText","id":"talk.vc.home_rank_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"总觉得你的背影变宽阔了，开始给人一种非常可靠的感觉。","en":"Is it just me, or have your shoulders gotten broader? Really ramps up your hero appeal.","ja":"なんだか背中が大きくなったねすっごく頼りがいが出てきた"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_sleeping_4#originalText","id":"talk.vc.home_rank_edith_sleeping_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"才一阵子不见，你居然变得这么强……欸，分享一下变强的秘诀好不好？","en":"Wow, look how strong you've gotten while I wasn't looking... Hey, what's your secret?","ja":"すこし見ない間に、こんなに強くなって……ちょっと、その秘訣を教えてよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_sleeping_5#originalText","id":"talk.vc.home_rank_edith_sleeping_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"光像现在这样我就能体会你到底有多强。强到像我这种程度根本敌不过你。","en":"It's obvious just how strong you've gotten. Even I don't hold a candle to you now.","ja":"こうしているだけでわかるよあなたがどれだけ強いかってあたしなんかじゃ、敵わないくらい"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_sleeping_1#originalText","id":"talk.vc.home_etc_edith_sleeping_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"任务达成，辛苦了。我来摸摸你的头当作给你的奖励。","en":"Good work on your mission. Let me reward you with a snuggle.","ja":"任務達成、お疲れさまご褒美に、なでなでしてあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_sleeping_2#originalText","id":"talk.vc.home_etc_edith_sleeping_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这是要给你的礼物喔。里头装了什么呢～我说……要不要打开来看看？","en":"A present for you is probably in here. Wanna open it?","ja":"あなた宛の贈り物何が入ってるんだろうね、開けてみない?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_edith_sleeping_3#originalText","id":"talk.vc.home_etc_edith_sleeping_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"下一项任务来了呢。为了提振精神，让我……抱一下就好！","en":"Aw, my next mission is in. Can I please have a little hug for inspiration before I go? Squee!","ja":"次の任務が来ちゃったね元気を注入するから少しだけ……ぎゅっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_soldier_1#originalText","id":"talk.vc.home_wait_eldrie_soldier_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我一定会成为集成骑士，将黑暗领域的恶鬼们驱逐出去！！","en":"By all odds, you will become an Integrity Knight and chase away those demons from the Dark Territory!","ja":"必ず整合騎士になってダークテリトリーの悪鬼どもを駆逐してみせる!!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_soldier_2#originalText","id":"talk.vc.home_wait_eldrie_soldier_2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"如果是很了解公理教会神圣术的人的话说不定会知道治疗妈妈的病的方法……","en":"If you are knowledgable on the Sacred Arts of the Axiom Church, then you probably know a way to cure my mother's illness...","ja":"公理教会の神聖術にお詳しい方なら母さんの病気を治す方法をご存知かもしれない……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_soldier_3#originalText","id":"talk.vc.home_wait_eldrie_soldier_3","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"爸爸好像想我继承军队……但我已经下定决心要成为集成骑士了。","en":"My father wanted me to continue serving in the military, but... I made up my mind to become an Integrity Knight.","ja":"父さんは私に軍を継いでほしいと思っているみたいだが……私は整合騎士になると心に決めたんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eldrie_soldier_4#originalText","id":"talk.vc.home_wait_eldrie_soldier_4","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"消灭黑暗领域的那些家伙，让患上妈妈那种病的人不再出现就好了。","en":"I hope that you'll be able to sweep up that army from the Dark Territory and that people won't get sick like my mother...","ja":"ダークテリトリーの輩を一掃して母さんのような病気になる人がいなくなればよいのだが……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_1#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我一直到最近，才总算能随心所欲地挥舞蓝蔷薇之剑。","en":"I feel like I've finally gotten the hang of this Blue Rose Sword.","ja":"最近になって、ようやく青薔薇の剣を思うとおりに扱えるようになってきたんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_2#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你跟最初相遇的时候一样，完全没有变呢。哈哈，我当然是在夸你啊。","en":"You haven't changed a bit since we met. Haha, of course, I meant that as a compliment!","ja":"君は、最初に会ったときから全然変わらないなはは、もちろん褒めてるんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_3#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那把黑色的剑跟你很搭呢。制服刚好也是黑的，你真的很适合黑色。","en":"That black sword suits you. With your black hair and clothing, black seems to be your color.","ja":"その黒い剣、君にピッタリだね制服も黒だし、君には黒い色が似合うんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_4#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"前阵子有个人说想找我学《艾恩葛朗特流》，我可以教那个人吗？","en":"Somebody came by earlier, wanting to learn Aincrad Style. You think we could we teach her?","ja":"この間、《アインクラッド流》を習いたいっていう子が来てさ教えてあげても、いいのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_5#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"希望有天能到别的国家增广见闻。我之所以会有这种想法，大概是被你影响吧。","en":"I'd love to travel abroad someday. You definitely influenced me there.","ja":"いつか、他の国へも行ってみたいねこんなことを思うようになったのはやっぱり君の影響かな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_6#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"《艾恩葛朗特流》的连续技最多可以接到几段啊？希望有一天我也能施展出超强的招式。","en":"Just how many attacks can you link together with Aincrad Style? I'd love to perfect a master attack someday.","ja":"《アインクラッド流》の連続技はどのくらいまで繰り出せるんだろういつか僕も、最高の技を出してみたい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_7#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我现在已经会使用各式各样的神圣术，回到村里之后应该能多少帮上大家的忙。","en":"I've become proficient in many Sacred Arts, so I hope I can help our village when we go back.","ja":"今はいろんな神聖術を使えるようになったから、村に戻ったら少しはみんなの役に立てるかも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_8#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"热闹的央都虽然很欢乐，但我有时也会怀念起卢利特那静谧的森林。","en":"I do enjoy Centoria's hustle and bustle, but sometimes I miss Rulid's quiet forests.","ja":"央都は賑やかで楽しいけど時々ルーリッドの、静かな森が懐かしくなるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_2nd_anniv_9#originalText","id":"talk.vc.home_wait_eugeo_uw_2nd_anniv_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你要是累了，就直接跟我说吧，用不着客气的。","en":"If you're tired, you should tell me. No secrets between friends, okay?","ja":"疲れてるなら、ちゃんと僕にはそう言ってくれよ遠慮なんかいらないからさ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_2nd_anniv_1#originalText","id":"talk.vc.home_touch_eugeo_uw_2nd_anniv_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你常喊着手刀来摸我的头，那到底是什么意思啊？","en":"You say the word \"chop\" a lot when you touch my head... Is there some secret meaning behind that?","ja":"よくチョップって言いながら頭を触ってくるけどそれってどういう意味なんだい?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_2nd_anniv_2#originalText","id":"talk.vc.home_touch_eugeo_uw_2nd_anniv_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你不要因为自己的手闲着，就跑来玩我的头发好不好？","en":"Look, I know you're bored, but could you please stop playing with my hair?","ja":"手持ち無沙汰だからって僕の髪をいじくり回すのは止めてくれないかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_2nd_anniv_3#originalText","id":"talk.vc.home_touch_eugeo_uw_2nd_anniv_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯？我嘴角沾到东西了吗？谢谢你帮我弄掉。","en":"Hm? Was there something on my lip? Thanks for getting it.","ja":"ん?口元に何かついてたかなありがとう、取ってくれて"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_2nd_anniv_4#originalText","id":"talk.vc.home_touch_eugeo_uw_2nd_anniv_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天的比试真是激烈呢，被你打到的地方还在隐隐作痛喔，但我想你也一样吧。","en":"Our sparring sure was intense today—now I'm sore all over. I imagine it's the same for you.","ja":"今日の立ち合いは激しかったねおかげで打たれた箇所が痛むよそっちも一緒だと思うけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_2nd_anniv_5#originalText","id":"talk.vc.home_touch_eugeo_uw_2nd_anniv_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我们都变得更强壮一些了呢。因为平常一直待在一起，所以不容易察觉就是了。","en":"Yes, we both gained a little muscle. Though it's hard to notice when we see each other all the time.","ja":"お互い、少しは逞しくなったよねずっと一緒にいるから普段は気付かないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_2nd_anniv_6#originalText","id":"talk.vc.home_touch_eugeo_uw_2nd_anniv_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……你要是有空捉弄我，怎么不去复习一下神圣术？","en":"If you're really that bored, maybe you should practice your Sacred Arts instead of poking me?","ja":"……僕にイタズラしている暇があったら、神聖術の復習をした方がいいんじゃないのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_2nd_anniv_7#originalText","id":"talk.vc.home_touch_eugeo_uw_2nd_anniv_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，抱歉……有什么事？我刚才在回忆从前，感叹自己真的跟以往很不一样了……","en":"Ah—sorry. Did you want something? I was just thinking... We've both come awfully far, huh?","ja":"あ、ごめん……何か用?ちょっと昔のことを考えててさ遠くに来ちゃったな……って"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_2nd_anniv_8#originalText","id":"talk.vc.home_touch_eugeo_uw_2nd_anniv_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喂，这样很痒啊！你不要突然摸我啦。不过，就算你提前讲我还是不愿意……","en":"Stop, that tickles! Don't tickle me out of the blue! And no, warning me first won't absolve you either.","ja":"おい、くすぐったいだろ!いきなり触るのはやめてくれよいや、予告されても嫌だけどさ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_1#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你是要去晨练吗？哈哈，我也是。那我们一起出门吧。","en":"Wait, are you going out for a morning practice? Haha, me too! Want to go together, then?","ja":"もしかして、朝の修練に行くのかい?はは、僕と同じだねそれじゃ、一緒に出かけようか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_2#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我还在当《伐木手》的时候，一天开始的时间也是固定的，早起对我来说不是那么难受的事。","en":"Back when I was a carver, I started the same time every morning, so I don't actually mind early mornings.","ja":"《刻み手》の時も、始める時間は決まってたからね。早起きはそんなに苦痛じゃないんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_3#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我已经叫过你了，就算你睡回笼觉睡过头，也不能怪我喔。","en":"Well, I tried to wake you up. Don't blame me if you fall asleep again and get up too late.","ja":"僕はちゃんと起こしたからね二度寝して寝坊しても僕のことは恨まないでくれよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_4#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我还在想你跑哪去了，原来是在这里睡午觉啊？你真的很爱睡呢。","en":"So there you are! Taking a nap, huh? You sure sleep a lot.","ja":"どこにいるのかと思ったらこんなところで昼寝かい?まったく、よく寝るなぁ君は"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_5#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我从一大早就在修练，现在是真的饿扁了。我们一起去吃中饭吧。","en":"That early-morning practice sure got me hungry... Wanna go out to lunch?","ja":"朝早くから修練しているからさすがにお腹がペコペコだよお昼ご飯、食べに行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_6#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天万里无云，可以看得很远呢。如果没有砍倒《基家斯西达》，是不是从这里也看得见呢？","en":"The sky's so clear you can see far today. If we hadn't cut it down, maybe we could see the Gigas Cedar.","ja":"今日は雲ひとつないから、遠くまでよく見えるね。伐り倒してなかったら《ギガスシダー》も見えたのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_7#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"偶尔换我来弄晚餐吧？别看我这样，我住在村里时都是自己做饭的。","en":"How about letting me cook tonight? Believe it or not, I used to take care of my own meals back in Rulid.","ja":"夕食、たまには僕が作ろうか?こう見えても、村にいるときは自分の食事くらいは作ってたからね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_8#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"晚上能像这样和人聊天真的很开心。我以前都不晓得呢。","en":"I love talking at night like this. Before I met you, I never knew it could be this much fun.","ja":"夜、こうやって誰かとおしゃべりするのは、すごく楽しいんだね今まで知らなかったよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_9#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"呼，我好像吃太多了。我去外面练习一下空挥，帮助消化好了。","en":"Phew...I think I overindulged. I'm gonna go walk some of it off.","ja":"ふう、少し食べ過ぎたかな腹ごなしに、外で少し素振りをしてくるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_10#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这么晚了还吃消夜？真是的，你什么时候准备好的啊？不用说，当然也有我的份吧？","en":"Isn't it a little late for dinner? Gosh, when did you even get that? I hope there's enough for me.","ja":"こんな時間に夜食かい?まったく、いつの間に用意したんだよそれで、僕の分もあるんだろうね?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_11#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我以前很怕做梦，因为我的梦，从来没有一次是开心的。不过……现在已经不一样了。","en":"I used to be afraid of my dreams. I knew nothing but nightmares. But now...everything's different.","ja":"以前は、夢を見るのが怖かった楽しい夢なんて一度も見なかったからでも……今は変わってきたんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_2nd_anniv_12#originalText","id":"talk.vc.home_time_eugeo_uw_2nd_anniv_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你这么晚还不睡，明天会很痛苦喔。虽然我也半斤八两就是了。","en":"You're going to hate yourself in the morning for staying up so late, you know? I'm guilty too, though.","ja":"こんな時間まで起きてると明日辛いよ?なんて、僕も同じだけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_uw_2nd_anniv_1#originalText","id":"talk.vc.home_day_eugeo_uw_2nd_anniv_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我其实很喜欢安息日结束后，大家同时上工的景象。","en":"I actually kind of like watching everyone get back to business as usual after a day of rest.","ja":"安息日が終わって、みんなが一斉に働き出す様子って実は結構好きなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_uw_2nd_anniv_2#originalText","id":"talk.vc.home_day_eugeo_uw_2nd_anniv_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"每天过着繁忙的生活，时间一下子就过去了呢。真希望能再多跟你说说话。","en":"Time sure flies when you keep busy. I wish we had more time to just relax and chat.","ja":"毎日忙しくしてると、あっという間に時間が過ぎていくね君とも、もっと話したいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_uw_2nd_anniv_3#originalText","id":"talk.vc.home_day_eugeo_uw_2nd_anniv_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"就算放假我也不会停止修练的。因为我必须变得更强。","en":"Even on my days off, I don't skip my training. I have to become stronger.","ja":"安息日だからって、修練は休まないよ。僕は、もっと強くならなきゃいけないんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_uw_2nd_anniv_4#originalText","id":"talk.vc.home_day_eugeo_uw_2nd_anniv_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"安息日转眼间就结束了呢。虽然这可能也是因为跟你一起过的关系。","en":"Days of rest end all too soon, don't they? Though I guess you made the time fly.","ja":"安息日はあっという間に終わっちゃうねふたりで過ごしてるせいもあるけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_1#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"新年快乐，我想今年一定会是个好年，因为是我们一起迎接的。","en":"Happy New Year. I just know it will be a good one. We're starting it together, after all.","ja":"新年、おめでとうきっと今年はいい年になるよこうして、ふたりで始められたから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_2#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"如果要举行把恶鬼赶出家门的仪式，那到尽头山脉去撒豆或许是最有效的呢。","en":"If we're trying to expel evil spirits, we should probably throw the beans all the way out to the End Mountains.","ja":"悪鬼を外に追い出すっていう儀式なら果ての山脈で豆をまくのが一番有効かもしれないね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_3#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这个点心是我自己买的。没有要送你，也不是别人送我的啦！","en":"I bought these candies myself! They were neither a gift for you, nor were they from someone else!","ja":"このお菓子は自分で買った物だよ君にあげる物でも、誰かからもらった物でもないってば!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_4#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"为女孩祈求幸福的习俗，我觉得很棒呢。希望也能在这一带传开来。","en":"I think praying for the happiness of girls is a beautiful custom. I hope the practice takes root here.","ja":"女の子の幸せをお祈りする風習って、素敵だと思うよこの辺りでも広まるといいね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_5#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"在没有收到对方礼物的情况下，由自己主动送的话，是不是很奇怪啊？","en":"Would it be too awkward to give someone a thank you gift if they never gave you a gift to begin with?","ja":"相手にもらってない場合はやっぱり、こっちから贈り物をするのは、変なのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_6#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"虽然我不介意你对我说谎，但我劝你还是别对其他人这样喔。最惨的情况，你说不定会被逮捕呢。","en":"I won't be upset if you lie to me, but you shouldn't lie to others. Worst case, you'll be arrested.","ja":"僕に嘘をついても怒らないけど他の人にはやらない方がいいよ最悪、捕まっちゃうかもしれないから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_7#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"放长假时，总会让人不晓得该做什么才好呢。什么？只有我会这样？","en":"I never know what to do on long vacations... Wait, am I the only one?","ja":"長い休みって、何をしていいかわからなくなるんだよねえ、僕だけかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_8#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天的比试真是累人呢。雨下个不停，害我全身都黏答答的。","en":"Our spar in the rain was torture, wasn't it? I'm all sticky from it.","ja":"今日の立ち合いは大変だったねずっと雨が降ってたしおかげで全身がドロドロだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_9#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"之所以要把心愿绑在高处的树枝上，果然是希望索鲁斯大人能看到吗？","en":"Do you tie your wishes high in the tree so that Solus can see them?","ja":"願い事を高い枝に結ぶのはやっぱり、ソルス様に見てほしいっていう理由なのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_10#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"每到夏至祭典我就会想起村子。不过，央都的祭典比村里的要热闹得多，真是欢乐呢。","en":"I always think of Rulid when the Solstice Festival approaches. But Centoria's festival is much livelier.","ja":"夏至祭が近づくと、村を思い出すよでも、央都のお祭りはそれよりずっと賑やかで、楽しいね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_11#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"夏天放了好久的假，我的身手说不定退步了，你可以陪我对练一下吗？","en":"That long summer break might have weakened our muscles. Want to spar a little?","ja":"夏の休みが長かったから体が鈍ったかもしれない少し立ち合ってくれないかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_12#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"像这样悠闲欣赏夜空，心情就会平静不少呢。这是因为有露那利亚大人庇佑吗？","en":"Staring up at the stars like this is pretty relaxing. I guess we have Lunaria to thank for that.","ja":"のんびり夜空を眺めるってなんだか落ち着くねルナリア様のご加護かな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_13#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_13","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"Trick or Treat……这也是《艾恩葛朗特流》的招呼语吗？因为我从来没听过。","en":"Trick or treat... Is that another Aincrad saying? Well, I've never heard it before.","ja":"トリックオアトリートも、《アインクラッド流》の挨拶なのかい?だって、聞いたことがないからさ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_2nd_anniv_15#originalText","id":"talk.vc.home_event_eugeo_uw_2nd_anniv_15","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"竟然悄悄地送礼物给孩子们，原来还有这种跟神明一样善良的人存在呢。","en":"Quietly leaving gifts for children... This Santa of yours sounds like a benevolent god.","ja":"子どもたちに贈り物をそっと届けるなんて、すごく優しい神様のような人がいるんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_uw_2nd_anniv_1#originalText","id":"talk.vc.home_season_eugeo_uw_2nd_anniv_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"在卢利特，这也是积雪终于要融化了的时期呢。又到了挥动斧头、挥洒汗水的季节了。","en":"I bet the snow in Rulid is starting to melt. This is the time of year axe- swinging used to make me sweat.","ja":"ルーリッドでも、ようやく雪が溶け出す頃だね斧を振ると汗をかく季節だ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_uw_2nd_anniv_2#originalText","id":"talk.vc.home_season_eugeo_uw_2nd_anniv_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"耐着热气修练确实不好受，但流汗过后再去洗澡真的很舒服呢。感觉很享受。","en":"Training in the heat is hard, but the cold bath afterwards is downright heavenly.","ja":"暑さの中の修練は辛いけど汗をかいた後のお風呂は気持ちいいね贅沢な気分になるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_uw_2nd_anniv_3#originalText","id":"talk.vc.home_season_eugeo_uw_2nd_anniv_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我头一次听到「食欲之秋」这个词，不过说来也对，这个季节确实有很多美食呢。","en":"I've never heard the saying, \"Autumn of Appetite\" before, but I guess autumn does have many tasty foods.","ja":"「食欲の秋」っていう言葉は初めて聞いたけど、確かに今の季節は美味しいものが多いよね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_uw_2nd_anniv_4#originalText","id":"talk.vc.home_season_eugeo_uw_2nd_anniv_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"自从开始使用蓝蔷薇之剑，我便不再讨厌寒冷了，感觉自己和寒气亲近了不少。","en":"Ever since I started using the Blue Rose Sword, I've come to like the cold. I feel like it's a part of me.","ja":"青薔薇の剣を振るようになってから寒さは嫌いじゃなくなったなんだか、寒さを身近に感じるんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_uw_2nd_anniv_2#originalText","id":"talk.vc.home_bd_eugeo_uw_2nd_anniv_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"自从得到天职以后，我就几乎没在庆生了……谢谢你，我很高兴。","en":"I haven't celebrated my birthday much since receiving my Calling... so thank you. I appreciate it.","ja":"天職をもらった頃から、誕生日ってあんまり祝ってなかったから……ありがとう、すごくうれしい"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_uw_2nd_anniv_3#originalText","id":"talk.vc.home_bd_eugeo_uw_2nd_anniv_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人的生日啊……他总爱吓唬我，我也想找个法子给他惊喜呢。","en":"It's Kirito's birthday, huh? Since he's always pulling pranks, I'd love to give him a scare for once.","ja":"キリトの誕生日か……いつもびっくりさせられてるから何とか驚かせたいんだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_uw_2nd_anniv_5#originalText","id":"talk.vc.home_bd_eugeo_uw_2nd_anniv_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"爱丽丝生日，我是想送她礼物，但我不晓得该送什么才好……欸，你陪我一起挑啦！","en":"I want to give Alice a birthday gift, but I don't know what to get her... Please! Help me pick something!","ja":"アリスの誕生日、贈り物をしたいけど何を贈ったらいいんだろう……ねえ、一緒に選んでくれよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_uw_2nd_anniv_1#originalText","id":"talk.vc.home_etc_eugeo_uw_2nd_anniv_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"使命达成，辛苦你了。为了备足下次出战的气力，希望你现在能好好休息。","en":"Good work on the assignment! But let's take a nice break before the next one.","ja":"使命達成、お疲れさま次に備えて、今はゆっくり休んでほしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_uw_2nd_anniv_2#originalText","id":"talk.vc.home_etc_eugeo_uw_2nd_anniv_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好像有礼物送达的样子，你确认过了吗？","en":"You've got a present. Do you want to open it?","ja":"贈り物が来てたみたいだけど確認したのかい?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_uw_2nd_anniv_3#originalText","id":"talk.vc.home_etc_eugeo_uw_2nd_anniv_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"新的使命已经确定了呢。虽然我觉得不用担心你，但你还是要小心应战啊。","en":"And a new assignment has begun. I know you're up to the task, but still be careful out there, okay?","ja":"新しい使命が決まったね君なら心配ないと思うけど気をつけて行ってきて"},"kind":"dialogue"},{"uid":"talk.vc.home_eugeo_halloween_wait_1#originalText","id":"talk.vc.home_eugeo_halloween_wait_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不给糖……我就要把你吃掉啰～！……骗你的啦嘻嘻～","en":"If I don't get any treats...  I'll eat you right up!  Hehe, how does that sound?","ja":"お菓子をくれないと……食べちゃうぞぉ〜! ……なんてね"},"kind":"dialogue"},{"uid":"talk.vc.home_eugeo_halloween_wait_2#originalText","id":"talk.vc.home_eugeo_halloween_wait_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我的变装比较恐怖吧？","en":"Isn't this costume scary?","ja":"僕の仮装の方が怖いだろ?"},"kind":"dialogue"},{"uid":"talk.vc.home_eugeo_halloween_touch_1#originalText","id":"talk.vc.home_eugeo_halloween_touch_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"要发糖果给大家啰！","en":"I'm giving treats out to everyone!","ja":"みんなにお菓子をあげるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_eugeo_uw_2022_new_year_wait_1#originalText","id":"talk.vc.home_eugeo_uw_2022_new_year_wait_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是不怎么常见的衣服呢。不过我很喜欢这个哦！感觉背都挺直了呢！","en":"Quite the rare outfit, huh? I dunno, I kinda like it. Makes me feel taller!","ja":"あんまり見たことない衣装だねでも僕これ、好きだな背筋が伸びる気がするよ"},"kind":"dialogue"},{"uid":"talk.vc.home_eugeo_uw_2022_new_year_wait_2#originalText","id":"talk.vc.home_eugeo_uw_2022_new_year_wait_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这装扮……感觉像是要把我打造成剑的形状呢。","en":"I feel like this outfit would help me with my Sword kata.","ja":"この格好……なんだか剣の型を整えてくれる気がするな"},"kind":"dialogue"},{"uid":"talk.vc.home_eugeo_uw_2022_new_year_touch_1#originalText","id":"talk.vc.home_eugeo_uw_2022_new_year_touch_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"暂时都穿着这衣服训练看看好了。","en":"I'm gonna go practice with it on.","ja":"しばらくこの服で稽古してみようかな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_1st_1#originalText","id":"talk.vc.home_wait_eugeo_1st_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你的神圣语是在哪里学的呢？是因为以前的天职才会说吗？","en":"How did you get so good at the Sacred Tongue? May that's what your previous Calling was?","ja":"君の神聖語は、どこで習ったものなんだろうねやっぱり前の天職なのかな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_1st_2#originalText","id":"talk.vc.home_wait_eugeo_1st_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天可以也麻烦你跟我比划吗？我有个想尝试一下的招式。","en":"Could you spar with me again today? There's something I want to test out.","ja":"今日も手合わせをお願いできるかい?少し試したいことがあるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_1st_3#originalText","id":"talk.vc.home_wait_eugeo_1st_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"仔细一想，我与你似乎已经相处了好长一段时间耶。","en":"Come to think of it, it feels like you and I have been together for ages now.","ja":"考えてみれば、君とはずいぶん長い間一緒にいる気がするよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_1st_4#originalText","id":"talk.vc.home_wait_eugeo_1st_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我必须变强……因为这次一定要守护好重要的事物。","en":"I need to become stronger... So that I can protect what's precious to me from now on.","ja":"僕は、強くならなきゃ……今度こそ、大事なものをちゃんと守るために"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_1st_9#originalText","id":"talk.vc.home_wait_eugeo_1st_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你是不是累了？要是累了就该休息。来，我帮你按一下肩膀。","en":"Are you getting a bit tired? Let's take a break. I'll try loosening up those shoulders of yours!","ja":"もしかして疲れてるのかい?だったら休まないとほら、肩をほぐしてあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_1st_1#originalText","id":"talk.vc.home_touch_eugeo_1st_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"要是剪成像涡罗学长的那种短发每天睡醒头发是不是就不会翘起来呢。","en":"I wonder if I getting my hair short like Volo's will solve my bed hair situation?","ja":"ウォロ先輩みたいに短い髪型にしたら寝癖もつかないのかなぁ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_1st_2#originalText","id":"talk.vc.home_touch_eugeo_1st_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你怎么把我当小孩子一样……我跟你年龄没差那么多吧！","en":"Hey, don't treat me like a child. You and I are practically the same age!","ja":"そんな、子どもにするみたいに……僕と君は、そんなに年齢は変わらないだろう!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_1st_4#originalText","id":"talk.vc.home_touch_eugeo_1st_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔……我的胸肌应该跟你差不多吧……","en":"Hmm...I think my pecs are just as strong as yours.","ja":"うーん、胸の筋肉は君と同じくらいかなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_1st_5#originalText","id":"talk.vc.home_touch_eugeo_1st_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"哦，怎么了吗？你会像这样逗我，通常都是有事要讲吧？","en":"Whoa there, what's wrong? You always seek attention when you want to talk.","ja":"おっと、どうしたんだい?そういう風に構ってくるのは何か話がある時だろう?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_1st_6#originalText","id":"talk.vc.home_touch_eugeo_1st_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"胸口是要害，所以一旦受到攻击，就会下意识摆出架式呢。","en":"Well, I always guard my chest when I'm attacked. It's a vital area after all.","ja":"胸は急所だから、攻撃されるとつい身構えちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_1st_1#originalText","id":"talk.vc.home_time_eugeo_1st_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"真难得耶，这个时间你居然已经起床了。","en":"Wow, I rarely see you up this early.","ja":"珍しいね、こんな時間にもう起きてるなんて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_1st_4#originalText","id":"talk.vc.home_time_eugeo_1st_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"都已经这么晚了啊。要吃什么？我们一起吃吧。","en":"It's getting late. What do you want for lunch? Want to eat with me?","ja":"もうこんな時間だね食事はどうする?一緒に食べようか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_1st_7#originalText","id":"talk.vc.home_time_eugeo_1st_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"就剩下一些了……我想把今天学到的东西先全部复习一遍。","en":"Just a bit more... I want to review everything I learned today so it sticks.","ja":"後もう少しだけ……今日教わったことは一通り復習しておきたいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_1st_10#originalText","id":"talk.vc.home_time_eugeo_1st_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"明明是大半夜，居然会像这样同时醒来……哈哈，总觉得好好笑喔。","en":"Haha, it's pretty funny how we've woken up at the same time even though it's so late!","ja":"夜中なのに、こうして同時に目が覚めるなんて……はは、なんだかおかしいね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_1st_1#originalText","id":"talk.vc.home_day_eugeo_1st_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天开始又有新的课程了呢。不晓得会上些什么呢，好期待喔。","en":"We're starting a new class today. I can't wait to see what we're learning.","ja":"今日からまた新しい授業だねどんな内容なのか楽しみだな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_1st_2#originalText","id":"talk.vc.home_day_eugeo_1st_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"虽然不停重复做同一件事，有时候会令我不安……但为了变强，这是不可或缺的。","en":"Sometimes all the repetition makes me anxious... But I need to train to become stronger.","ja":"同じことの繰り返しだと時々不安になるけど……強くなるためには、やらないと"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_1st_3#originalText","id":"talk.vc.home_day_eugeo_1st_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"安息日不能挥剑……如果是挥斧头的话，是否就不算违反禁忌目录呢？","en":"On Days of Rest we're forbidden from swinging a sword... But maybe a practice staff doesn't count?","ja":"安息日には剣を振れない……もし斧だったら、振っても禁忌目録違反にはならないのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_1st_4#originalText","id":"talk.vc.home_day_eugeo_1st_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天真是开心，我明天也能继续努力了。或许是托了你的福。","en":"Thanks to you, I had so much fun today that I'm inspired to do it all over again tomorrow.","ja":"今日が楽しかったから明日も頑張れるよ君のおかげかな"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_1st_1#originalText","id":"talk.vc.home_season_eugeo_1st_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"果然春天一到，心情就会不自觉开朗起来呢，因为天气终于要变暖和了。","en":"I'm always happier when you're around. It's like the sun finally coming out after a storm.","ja":"やっぱり、春が来るとなんだか気持ちが華やぐんだやっと暖かくなるんだって"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_1st_2#originalText","id":"talk.vc.home_season_eugeo_1st_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"在炎热的夏日不停挥剑，会变得什么也不想，然后不知不觉天就黑了。","en":"On hot summer days, it's easy to lose track of time practicing and be surprised by nightfall.","ja":"夏の暑い日にずっと剣を振ってると、無心になっていつの間にか夜になってるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_1st_3#originalText","id":"talk.vc.home_season_eugeo_1st_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"差不多是准备收成的季节了。以前在村子里的时候，村民会全体出动一起去收割喔。","en":"It's almost harvest time. When I lived in Rulid, all the villagers would help with the harvest.","ja":"そろそろ収穫の季節だね村にいた頃は、みんな総出で刈り入れをやったんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_1st_4#originalText","id":"talk.vc.home_season_eugeo_1st_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"即使天气冷，只要没下雪就不算太难受。","en":"I don't mind the cold weather as long as it doesn't snow.","ja":"寒くても、雪がなければあんまり辛くないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_1#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"对了，在萨卡利亚照顾马匹的时候，我也像这样睡在你旁边耶。","en":"That reminds me, when we were caring for the horses in Zakkaria, we slept side by side like this.","ja":"そういえば、ザッカリアで馬の世話をしていた時もこうして隣同士、寝ていたよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_2#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"以前我在村子里的时候，即使和家人一起住，还是感到很孤单。但我现在身旁有你。","en":"Even when I lived in Rulid with my family, I always felt so alone. But now, I have you.","ja":"村にいた時は、家族と住んでいてもひとりぼっちだったでも、今は君がいる"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_3#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"说不定我从一开始就有这种想法，认为你或许……能够改变我。","en":"Maybe I always knew it would happen. That you would... change me for the better.","ja":"もしかしたら、最初から思っていたのかもしれない君が僕を……変えてくれるかもって"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_4#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喂喂，你是不是又在打什么歪主意了？你每次露出那副表情都是这样。","en":"Hey, I hope you don't have mischief on the brain. You always do when you make that face.","ja":"こら、またおかしなことを考えてるんじゃないだろうねそんな顔してる時はいつもそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_5#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你在睡觉的时候，由我负责保护你。所以你尽管睡吧。","en":"I'll watch over you while you sleep. So stay in bed as long as you like.","ja":"君が寝ている間は僕が君を守るだからいくらでも寝ててよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_6#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那个……谢谢你。没什么，只是突然想向你道谢而已，反、反正又不会怎样！","en":"Um...thank you. Er, well, I just felt like saying it. Wh-Who cares why!","ja":"その……ありがとういや、なんだか急に言いたくなってべ、別にいいだろ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_7#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我们一起睡觉的次数，已经多到数不清了。真亏我永远都找得到话题和你聊。","en":"Countless nights we've slept side- by-side like this. I'm shocked we haven't run out of stories to tell.","ja":"君とこうして一緒に寝るのはもう数え切れないよね。我ながらよく話が尽きないなって思うよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_8#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唉～今天好累喔。为了明天，还是早点睡吧。千万不要熬夜喔。","en":"Ahh... Today sure was exhausting. Let's turn in early tonight so we can be well-rested for tomorrow.","ja":"はあー、今日は疲れたね明日に備えて早く寝よう夜更かしはしないようにね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_eugeo_uw_sleeping_9#originalText","id":"talk.vc.home_wait_eugeo_uw_sleeping_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"真是的，你总是倒头就睡耶。我实在很羡慕你。","en":"Goodness, you always fall asleep so quickly. I'm starting to get jealous here.","ja":"まったく、本当に君はいつも寝付くのが早いよねうらやましくなっちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_sleeping_1#originalText","id":"talk.vc.home_touch_eugeo_uw_sleeping_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"小时候，你常常像这样把我的头发弄乱……咦？不过那时候我们还没……","en":"When I was little, I remember having my hair tussled like this a lot... But wait, we hadn't met yet.","ja":"小さい頃は、よくこうやって頭をクシャクシャって……あれでも僕たちはその頃まだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_sleeping_2#originalText","id":"talk.vc.home_touch_eugeo_uw_sleeping_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"头发好像有点长了。再不去剪，可能会妨碍到修练。","en":"I know, it's getting long. I'd better cut it so it won't get in the way when I train.","ja":"少し伸びてきたかなそろそろ切らないと、修練の時に邪魔になっちゃうな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_sleeping_3#originalText","id":"talk.vc.home_touch_eugeo_uw_sleeping_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"干嘛一直摸我的脸啊？这一点都不好玩吧？","en":"Why are you touching my face? It can't be that amusing.","ja":"なんだよ、僕の顔をなで回したって何にも楽しくないだろ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_sleeping_4#originalText","id":"talk.vc.home_touch_eugeo_uw_sleeping_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我是不是有长一点肌肉了？这都多亏了哥鲁哥罗索学长的指导。","en":"Have I bulked up a little? Golgorosso's training sessions really have been a godsend.","ja":"少しは、筋肉がついてきたかな?これもゴルゴロッソ先輩の指導の賜物だよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_sleeping_5#originalText","id":"talk.vc.home_touch_eugeo_uw_sleeping_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不需要担心，多亏了赛鲁卡和你，在北方洞窟受的伤已经痊愈了。","en":"Don't worry, my wounds from that cave incident are gone now. I have you and Selka to thank for that.","ja":"心配しなくても、北の洞窟でやられた傷は、もう残ってないよセルカと君のおかげでね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_sleeping_6#originalText","id":"talk.vc.home_touch_eugeo_uw_sleeping_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喂喂，很痒耶！我好不容易才有睡意的说，你这家伙真是……","en":"Hey, stop! That tickles, you jerk! And I was just finally drifting off to sleep, too...","ja":"ちょっと、くすぐったいだろ!?やっと眠くなってきたところなのにまったく君ってヤツは……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_sleeping_7#originalText","id":"talk.vc.home_touch_eugeo_uw_sleeping_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好险！我再怎么笨，被你偷袭那么多次后，也已经学会怎么闪了。","en":"Whoa, there! Even I have boundaries and I'm not gonna let you cross them.","ja":"おっと! さすがに僕だってこれだけちょっかい出されれば避けられるようになるさ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_eugeo_uw_sleeping_8#originalText","id":"talk.vc.home_touch_eugeo_uw_sleeping_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你该不会是想拿我来测试赛鲁鲁特流的招式吧？","en":"I hope you're not going to practice Serlut style on me.","ja":"まさか、僕の体でセルルト流の実験をする気じゃないだろうね?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_sleeping_1#originalText","id":"talk.vc.home_time_eugeo_uw_sleeping_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"早安啊。好了，再不起床就要迟到啰。","en":"Good morning. Come on now, get up or you'll be late.","ja":"おはようほら、そろそろ起きないと遅刻しちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_sleeping_2#originalText","id":"talk.vc.home_time_eugeo_uw_sleeping_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"受到你的影响，连我也跟着熬夜了……今天早上真难熬啊。","en":"You made me stay up too late last night...and I'm paying for it today.","ja":"君につられて夜更かししちゃったから……今日は朝が辛いよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_sleeping_4#originalText","id":"talk.vc.home_time_eugeo_uw_sleeping_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"从早上就一直睡总觉得好有罪恶感……我还是去挥挥剑好了。","en":"Staying in bed all morning makes me feel a bit guilty... I think I'll go get a few swings in.","ja":"朝からずっと寝てると、なんだか罪悪感が……やっぱり僕は、ちょっと素振りしてくるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_sleeping_5#originalText","id":"talk.vc.home_time_eugeo_uw_sleeping_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我把饭菜端来啰。真是的，都几岁了，还要在床上吃饭。","en":"I've brought you some breakfast. You want to eat it in bed? Sheesh, you're like a spoiled child.","ja":"ほら、食事持ってきたよまったく、ベッドで食べたいなんて子どもみたいだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_sleeping_7#originalText","id":"talk.vc.home_time_eugeo_uw_sleeping_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"下次的神圣术考试没问题吗？这次你就算来求我，我也不会再帮你了。","en":"Are you prepared for the next Sacred Arts exam? I'm not bailing you out this time.","ja":"次の神聖術試験は大丈夫かい今度こそ、僕に甘えてきても手助けしてあげないからね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_sleeping_8#originalText","id":"talk.vc.home_time_eugeo_uw_sleeping_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"和你一起睡觉时，常常会做不可思议的梦。像是小时候的我们待在一起之类的。","en":"Whenever I sleep next to you, I have really strange dreams. Like...of us being kids together.","ja":"君と一緒に寝ていると、不思議な夢を見ることが多いんだ小さい僕たちが、一緒にいる夢とか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_sleeping_10#originalText","id":"talk.vc.home_time_eugeo_uw_sleeping_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"抱歉，吵醒你了吗？我实在忍不住想复习今天学长教我的东西。","en":"Sorry, did I wake you? I just had to practice everything Golgorosso taught me today.","ja":"ごめん、起こしちゃったかな今日先輩に教わったことどうしても復習しておきたくて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_uw_sleeping_11#originalText","id":"talk.vc.home_time_eugeo_uw_sleeping_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"每当仰望夜空，不知为什么就会想到你。因为你眼睛和头发都是夜空的颜色吗？","en":"When I look at the night sky, why do I always think of you? Is it because of your eyes and hair?","ja":"夜中に空を見るとなぜか君のことを思うんだ瞳や髪が、夜空の色だからかな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_uw_sleeping_1#originalText","id":"talk.vc.home_day_eugeo_uw_sleeping_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"真是的，这个星期才刚开始，你打算睡到什么时候？连我都跟着起不来了。","en":"Wow, starting off the week by staying in bed all day? Now you're making it hard for me to get up.","ja":"まったく、週の初めからいつまで寝るつもりだい?僕まで起きられないじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_uw_sleeping_2#originalText","id":"talk.vc.home_day_eugeo_uw_sleeping_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天真的好累。一躺下就不想爬起来了。","en":"Today was exhausting, wasn't it? I don't think I'll be able to get up once I lie down.","ja":"今日はくたびれたね一度横になっちゃうと起き上がるのが辛いよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_uw_sleeping_3#originalText","id":"talk.vc.home_day_eugeo_uw_sleeping_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"安息日有打算去哪吗？还是只想窝在这里？","en":"Do you have any plans to go out on the Day of Rest? Or would you rather just stay in?","ja":"安息日は、どこかにでかける予定があるの?それとも、ここで巣ごもりかな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_uw_sleeping_4#originalText","id":"talk.vc.home_day_eugeo_uw_sleeping_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天过得好开心。有人能陪我躺着聊过去的事情，感觉真愉快呢。","en":"I had a lot of fun today. And it's nice having someone to talk to while lying in bed.","ja":"今日は楽しかったねこんな風に寝ながら思い出を語る相手がいるって、楽しいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_1#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"像这样边聊天边跨年，对我们来说应该是第一次吧？","en":"Well, this is the first time I've ever rung in the new year while talking all night.","ja":"こうやって、ふたりでおしゃべりしながら年を越しちゃったのはさすがに初めてだね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_2#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"把鱼头挂在入口真的有效果吗？毕竟你老是喜欢说一些真假难辨的事情。","en":"Does hanging fish heads in the doorway really ward off evil? I never know when you're joking.","ja":"魚の頭を入り口に飾るって本当に効果があるのかい?君の言うことはいつも怪しいからなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_3#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天不是女生送点心给男生的日子吗？你到底在期待什么啊？","en":"February 14th is the day girls give boys candy, right? So why are you getting your hopes up?","ja":"今日は、女性が男性にお菓子を贈る日なんだろう?何を期待してるんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_4#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"两个男生一起庆祝女生的节日，气氛也热络不起来啊………不过，这个点心还满好吃的。","en":"It doesn't feel exciting as boys, celebrating a holiday for girls... but these snacks sure are tasty.","ja":"男ふたりで、女の子のお祝いをしても、盛り上がらないよね……でも、このお菓子はおいしいね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_5#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦，回送给我的？谢、谢谢你……下次换我得回送你东西了。","en":"Oh, you have a thank you gift for me? Thanks... I'd better give you a thank you gift back later.","ja":"え、僕にお返し?あ、ありがとう……今度はまた僕の方からお返しをしないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_6#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"既然一开始就知道这一天大家会撒谎，我再怎么样也不会被骗。来啊，想撒谎随时奉陪。","en":"If I already know in advance that you're going to lie, I can't be fooled. So, go ahead.","ja":"嘘をつくって最初からわかってるなら、僕だって騙されないよさあ、いつでもどうぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_7#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我承认休息也算是修行的一环，但是难得有那么长的假期……","en":"I know that rest is a key part of training...but I still hate to waste such a long holiday resting.","ja":"体を休めるのも修行のうちっていうのは認めるけどせっかくの長いお休みなのに……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_8#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"以前当伐木手的时候，一到了多雨的季节就会很忧郁。即使到了现在，握不稳斧柄的感觉还留在我手上。","en":"When I used to be a carver, rainy season was always so dreary. I can still feel the slippery axe handle.","ja":"刻み手だった頃は、長い雨の季節は憂鬱だったなあ。今でも斧の柄が滑る感触が手に残ってる"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_9#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"要在这张纸上写下愿望吗？……不过，愿望被人看到，还挺让人不好意思的。","en":"I'm supposed to write wishes on these papers? But...I don't want anyone else to see my wishes.","ja":"この紙に願い事を書くのかい?……でも、願い事を人に見られちゃうのは、照れくさいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_10#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"夏天的索鲁斯大人十分猛烈，但正因为如此，才更不该疏于锻炼。","en":"Solus's heat is brutal in the summer, but that's no excuse to slack on the training.","ja":"夏のソルス様が苛烈だけどこういう時こそ、鍛錬をさぼったらいけないと思うんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_11#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"夏天的假期就到今天为止了。结果感觉就连放假也一直和你在一起耶。","en":"Summer vacation ends today... It feels like we wound up spending the whole vacation together.","ja":"夏のお休みも、今日で終わりだねなんだか、休みの間も結局君とずっと一緒だったなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_12#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"听说今晚的露那利亚特别漂亮。平常我不太会注意，不过今天就好好欣赏一下吧。","en":"I hear Lunaria is magnificent tonight. I don't usually stare at her, but I think I will tonight.","ja":"今夜はルナリアが見事なんだって普段あまり眺めることはないけど今日はじっくり見てみようかな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_13#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_13","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不给糖就捣蛋？这种节庆该不会是你自己随便掰的吧？","en":"Trick or treat... Are you sure you didn't come up with this festival?","ja":"お菓子をくれないとイタズラするなんて……もしかして、君が勝手に考えたお祭りなんじゃないの?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_eugeo_uw_sleeping_15#originalText","id":"talk.vc.home_event_eugeo_uw_sleeping_15","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"虽然下雪会造成很多麻烦，但一看到雪白的大地，就会不自觉地肃然起敬。","en":"Snow is a hassle to deal with, but the sight of white on the ground makes me feel so calm.","ja":"雪が降ると大変だけど真っ白に染まった大地を見るとなんとなく、身が引き締まるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_uw_sleeping_1#originalText","id":"talk.vc.home_season_eugeo_uw_sleeping_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"春天是我们相遇的季节。我当然不会忘，因为是你改变了我。","en":"Spring is when I met you and I'll never forget it. You're the one who made me the person I am.","ja":"春は、君と出会った季節だねもちろん忘れないよ僕を変えてくれたのは、君だから"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_uw_sleeping_2#originalText","id":"talk.vc.home_season_eugeo_uw_sleeping_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"流了好多汗喔。在躺上床之前，去洗个澡应该会比较好。","en":"You've worked up quite a sweat. You should probably rinse off before you get into bed.","ja":"ずいぶん汗かいちゃったねベッドに入る前に、水浴びをしてきた方がいいんじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_uw_sleeping_3#originalText","id":"talk.vc.home_season_eugeo_uw_sleeping_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"秋季的暴风雨好像已经来了，不知道卢利特那边情况怎样。希望大家都平安无事。","en":"Looks like there's an autumn storm coming. I hope everyone in Rulid will be okay.","ja":"秋の嵐が来てるみたいだよルーリッドの方は大丈夫かなあみんな無事だといいんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_season_eugeo_uw_sleeping_4#originalText","id":"talk.vc.home_season_eugeo_uw_sleeping_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"央都的冬天不像卢利特那么冷，所以应该不用穿得太厚吧？","en":"Winters in Centoria aren't as cold as Rulid, so I guess we don't have to layer up so much.","ja":"央都の冬は、ルーリッドほど寒くないから、あんまり着込まなくても大丈夫かな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_uw_sleeping_2#originalText","id":"talk.vc.home_bd_eugeo_uw_sleeping_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"谢谢你……为我庆生。要是以后爱丽丝也有机会一起庆祝就好了。","en":"Thanks for celebrating my birthday! I hope Alice can join us someday...","ja":"誕生日……祝ってくれてありがとう。いつかアリスも一緒に祝えたらいいな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_uw_sleeping_3#originalText","id":"talk.vc.home_bd_eugeo_uw_sleeping_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"生日快乐。我还没想到要送你什么，要不要和我一起去买？","en":"Happy Birthday! I couldn't think of anything to give you, so do you want to go shopping?","ja":"誕生日、おめでとう何を贈ろうか思いつかなかったから一緒に買い物に行かないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_eugeo_uw_sleeping_5#originalText","id":"talk.vc.home_bd_eugeo_uw_sleeping_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"爱丽丝的生日……我一直都记在心上，每年都不忘在心里帮她庆祝。","en":"It's Alice's birthday... I remember it every year. The best I can do is wish her well from afar.","ja":"アリスの誕生日……毎年忘れず、気持ちだけはお祝いしてるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_uw_sleeping_1#originalText","id":"talk.vc.home_etc_eugeo_uw_sleeping_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"作业做完了吗？没想到你这次这么快。那么，要不要在这边放松一下？","en":"Have you finished your assignment? That was fast for you. Well, want to come hang out with me?","ja":"課題は終わったの?君にしては早いんだねなら、こっちでゆっくりしたら?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_uw_sleeping_2#originalText","id":"talk.vc.home_etc_eugeo_uw_sleeping_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"送你的礼物一直都很多，真是让人惊讶。","en":"You always get so many presents. It never ceases to amaze me.","ja":"いつも君への贈り物はたくさんあるから、驚いちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_eugeo_uw_sleeping_3#originalText","id":"talk.vc.home_etc_eugeo_uw_sleeping_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"下次的作业没问题吗？不早点开始准备的话，到时可就糟糕了。","en":"Will you finish your assignment on time? You'd better get it done as soon as you can.","ja":"次の課題、大丈夫?早めに手をつけておかないといざとなったら大変だよ"},"kind":"dialogue"},{"uid":"talk.vc.home_fanatio_sweater_wait_1#originalText","id":"talk.vc.home_fanatio_sweater_wait_1","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"强大也分许多种类，这是阁下教会我的。","en":"There are many different kinds of strengths out there. You taught me that. ","ja":"強さには、いろいろな種類があるそう教えて下さったのは閣下です"},"kind":"dialogue"},{"uid":"talk.vc.home_fanatio_sweater_wait_2#originalText","id":"talk.vc.home_fanatio_sweater_wait_2","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"女性也有女性的强大之处。","en":"Yes, women have a strength of their own.","ja":"女性には女性の、強さがあるものです"},"kind":"dialogue"},{"uid":"talk.vc.home_fanatio_sweater_touch_1#originalText","id":"talk.vc.home_fanatio_sweater_touch_1","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"从最初遇见您的那一刻起，我就一直仰慕着您……","en":"I've loved you ever since our first encounter...","ja":"最初に会った時からずっとお慕いしておりました……"},"kind":"dialogue"},{"uid":"talk.vc.home_fanatio_sweater_touch_2#originalText","id":"talk.vc.home_fanatio_sweater_touch_2","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"像这样被您抚摸着头发，感觉舒服到可以就这样入睡。","en":"Whenever you pet my hair, I get so happy and can just fall asleep in your laps right there and then.","ja":"そうして髪を撫でられていると気持ちがよくて眠ってしまいそうになります"},"kind":"dialogue"},{"uid":"talk.vc.home_fanatio_sweater_touch_4#originalText","id":"talk.vc.home_fanatio_sweater_touch_4","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"从阁下的手可以感觉到非常柔和的温暖。我也可以触碰您吗……？","en":"Your hands feel so soft and warm. Can I touch them...?","ja":"閣下の手からはとても優しいぬくもりを感じます私も触れて、いいですか……?"},"kind":"dialogue"},{"uid":"talk.vc.home_fanatio_sweater_touch_5#originalText","id":"talk.vc.home_fanatio_sweater_touch_5","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"活在悠久之时的集成骑士，只要脱下盔甲，也只是普通的男女。","en":"Even for the immortal Integrity Knights, we're just men and women when we take off our armor.","ja":"悠久の時を生きる整合騎士も鎧を抜いでしまえばひとりの男と女なんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_1#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们已经完全融入这个世界了呢。感觉回到现实后会很辛苦。","en":"We've gotten a bit too comfortable in this world. I don't know if we can handle the real world now.","ja":"もうすっかりこの世界に馴染んじゃったな現実に戻ったら大変そうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_2#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"真希望我们不是在玩死亡游戏，而是单纯地在这个艾恩葛朗特享受冒险。","en":"I wish we could've just experienced Aincrad normally instead of as a death game.","ja":"デスゲームなんかじゃなくて普通にこのアインクラッドを冒険してみたかったよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_3#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"《KoB》的副团长大人跟我这个封弊者待在一起，没关系吗？","en":"Are you sure the esteemed Vice Commander of the KoB should be seen with a dirty beater like me?","ja":"《KoB》の副団長サマがビーターの俺なんかと一緒にいて大丈夫か?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_4#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"在这个地方，就算是熟人也不能掉以轻心啊。……不过，我用不着提防妳就是了。","en":"I don't let my guard down around anyone here—even people I know... But I can trust you.","ja":"ここじゃ、たとえ知り合いでもうかつに気を許せないよ……まあ、君なら大丈夫だけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_5#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"欸，妳可以再做便当给我吃吗？就算找遍山珍海味也不会有比那更好吃的了。","en":"Hey, can you make me lunch again? I can't find anything here that tastes nearly as good as your cooking.","ja":"なあ、また弁当を作ってくれないかあれよりおいしい物なんて探しても見つからないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_6#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"情报商人、店老板、冶炼师女孩……还有妳。没想到也有人愿意善待我这样的人呢。","en":"So many people are good to me. The informant, the shopkeep, the blacksmith...and you.","ja":"情報屋に、ショップの主に鍛冶屋の子……それに君。こんな俺でも、よくしてくれる人はいるんだな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_7#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我一直认为自己是独行玩家，但到头来却老是在接受别人的帮助呢……特别是妳。","en":"I'd resigned myself to being a solo player all this time, but I keep getting rescued...especially by you.","ja":"俺はずっとひとりでプレイしてきたつもりだけど、結局誰かに助けてもらってるんだよな……特に、君に"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_8#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"有空的话，要不要一起解任务？我自己一个人好累喔。","en":"If you've got time, do you want to go on a quest with me? It's too risky going alone.","ja":"時間があるなら、一緒にクエストやってくれないか?ひとりじゃきついんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_kirito_sao_2nd_anniv_9#originalText","id":"talk.vc.home_wait_kirito_sao_2nd_anniv_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"怎么啦，在那边发呆？妳要是累了，我们再一起午睡吧。","en":"You look tired. I'm fine with taking another nap together, if you need it.","ja":"どうしたんだ、ぼーっとして疲れてるなら、また一緒に昼寝でもしようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_sao_2nd_anniv_1#originalText","id":"talk.vc.home_touch_kirito_sao_2nd_anniv_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"游戏刚开始的时候，我的头发其实长到下巴这边呢。现在想起来还真害羞啊。","en":"When I started the game, my hair was actually down to my chin. Kind of embarrassed by that now.","ja":"ゲームスタート時は実は顎くらいまである長髪だったんだ今考えると、ちょっと恥ずかしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_sao_2nd_anniv_2#originalText","id":"talk.vc.home_touch_kirito_sao_2nd_anniv_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂、喂……妳突然把脸凑得这么近，是有什么事啦？","en":"H-Hey...what's wrong? Why so close all of a sudden?","ja":"お、おい……いきなりそんな顔近づけてどうしたんだよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_sao_2nd_anniv_3#originalText","id":"talk.vc.home_touch_kirito_sao_2nd_anniv_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们这样要是被别人看到，应该不太妙吧……？不，我是不在意啦。","en":"Uh, won't we get in trouble if someone sees us like this? N-Not like I mind it or anything...","ja":"こんなところ、誰かに見られたらまずいんじゃないのか……?いや、俺は別に、いいんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_sao_2nd_anniv_4#originalText","id":"talk.vc.home_touch_kirito_sao_2nd_anniv_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"因为我本身注重AGI，所以铠甲都会尽量挑轻一点的。","en":"I like to build for agility. That's why I always pick the lightest armor possible.","ja":"俺はAGI優先型だからな鎧はできる限り、軽い物を選んでるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_sao_2nd_anniv_5#originalText","id":"talk.vc.home_touch_kirito_sao_2nd_anniv_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这、这样很痒啦！不要突然摸我啦。","en":"H-Hey, that tickles! A little warning, maybe?","ja":"く、くすぐったいだろ!いきなり触るのは止めてくれよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_kirito_sao_2nd_anniv_6#originalText","id":"talk.vc.home_touch_kirito_sao_2nd_anniv_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我好歹也是健康的正常男性，妳这样摸我的话，我会……觉得很困扰的……","en":"Y'know, I am a normal, healthy guy. So when you touch me like that... my mind goes somewhere else...","ja":"一応俺も健康な一般男性なわけでそういう風にされると、こう……いろいろ困るというか……"},"kind":"dialogue"}]};
